body:
Hi @bartekbp 

It is a bug that we can reproduce with this code:

```ts

import { Hono } from 'hono'
import { validator } from 'hono/validator'

const app = new Hono()

app.post(
  '/',
  validator('json', (v) => v),
  async (c) => {
    const { name } = c.req.valid('json')
    return c.json({
      name,
    })
  }
)

describe('Validator', () => {
  test('should return valid response for content-type application/json with a charset', async () => {
    const res = await app.request('/', {
      method: 'post',
      body: JSON.stringify({
        name: 'foo',
      }),
      headers: {
        'content-type': 'application/json; charset=utf-8',
      },
    })
    expect(res.status).toBe(200)
    expect(await res.json()).toEqual({ name: 'foo' })
  })
})
```

I'll fix it soon. Thank you very much!
